            float2 uv2 = float2(a.x / iResolution.x, exp(a.y));
            float2 id = floor(uv * AMOUNT);
                float2 scaleVec;
                scaleVec = float2(scale*stretch.x,scale*stretch.y);
                uv2 /= scaleVec;
            float shift = glitchAmplitude * pow(fbm(uv2, int(rand(id) * DISTORT),
                          glitchBlockiness, glitchNarrowness), glitchMinimizer);
            float scanline = abs(cos(uv.y * 400.0));
            scanline = smoothstep(0.0, 2.0, scanline);
            shift = smoothstep(0.00001, STEP, shift);
                float colR;
                if ((rcolor>0.5)) { colR = amzTexture(0, float2(uv.x + shift, uv.y)).r * (1. - shift); }
                else { colR = amzTexture(0, float2(uv.x - shift, uv.y)).r * (1. - shift); }
                float colG;
                if ((gcolor>0.5)) { colG = amzTexture(0, float2(uv.x + shift, uv.y)).g * (1. - shift); }
                else { colG = amzTexture(0, float2(uv.x - shift, uv.y)).g * (1. - shift); }
                float colB;
